//! Native differential test (tests module at the bottom). After the anim_list_load / cutscene_parse_characters
//! stack-argument fix (callee arg counts were under-counted: 0xa7ca70 takes 2, 0x6d0c00 takes 4) and with 27 pure leaf
//! callees now run for real (REAL), the result is the same: 57 of 58 functions passed 120/120 random trials
//! (original bytes vs the Rust port, same registers / memory / stack, callees stubbed identically; calls, memory
//! writes, return value and ESP balance compared). 1 FAILED and is excluded from install(): xtbl_load_effects
//! (0x50d000, 115/120, a register value passed to callee 0xbdcb30 differs in trial 53). Many trials end in a matching
//! fault / call cap (both sides identical), so depth is moderate. To run (note the /BASE value, it differs from the other ports' tests):
//! RUSTFLAGS="-C link-arg=/DYNAMICBASE:NO -C link-arg=/BASE:0x10000" cargo test --release -p sr2-hook
//! --target i686-pc-windows-msvc port_tables -- --ignored --nocapture
//!
//! Large straight-line startup / load functions, ported mechanically.
//!
//! Each body below is a basic-block state machine produced by scratchpad/tables/lifter.py from the
//! original bytes: every x86 instruction of the function (and of its out-of-line stubs after the
//! final `ret`) becomes one statement here, in the original order. Memory goes through `rd`/`wd`,
//! the registers are locals, the stack frame is a local buffer that holds the pushes, locals and
//! the stack arguments at the same offsets as the original (so `lea reg, [esp+X]` pointers handed to
//! callees still point at real, writable memory), the flags are computed eagerly, and callees are
//! called BY ADDRESS through `call_regs` with the live registers and the stack arguments at that
//! point. x87 instructions are replayed as the original bytes (`.byte`) or the same memory form, so
//! the FPU state is the real one.
//!
//! How each port was checked (scratchpad/tables/validate.py): the original bytes run under an x86
//! emulator and a python rendering of the same statements runs side by side, with callees stubbed
//! identically; every memory write, every call (target, registers, stack words) and the return
//! value must match over 30+ randomised runs, and the emulated ESP must balance at the `ret`.
//!
//! These run at startup or load, so there is no shadow. Each function counts its executed call
//! sites; the first call logs them against the static call-site count of the body.

#![allow(clippy::all)]

use crate::portlib::*;
use crate::log;
use std::sync::atomic::{AtomicBool, AtomicU32, Ordering};

unsafe fn rw(p: usize) -> u16 {
    unsafe { *(p as *const u16) }
}

unsafe fn ww(p: usize, v: u16) {
    unsafe { *(p as *mut u16) = v }
}

/// `rep movs / stos / cmps / scas` with the direction flag clear. The flags tuple is only returned for the
/// compare forms that ran at least once (zf, sf, cf, of, pf).
unsafe fn rep_op(kind: &str, eax: u32, mut ecx: u32, mut esi: u32, mut edi: u32) -> (u32, u32, u32, u32, Option<(bool, bool, bool, bool, bool)>) {
    unsafe {
        let mut fl = None;
        match kind {
            "rep movsd" => while ecx != 0 { wd(edi as usize, rd(esi as usize)); esi = esi.wrapping_add(4); edi = edi.wrapping_add(4); ecx -= 1; },
            "rep movsw" => while ecx != 0 { ww(edi as usize, rw(esi as usize)); esi = esi.wrapping_add(2); edi = edi.wrapping_add(2); ecx -= 1; },
            "rep movsb" => while ecx != 0 { wb(edi as usize, rb(esi as usize)); esi = esi.wrapping_add(1); edi = edi.wrapping_add(1); ecx -= 1; },
            "rep stosd" => while ecx != 0 { wd(edi as usize, eax); edi = edi.wrapping_add(4); ecx -= 1; },
            "rep stosw" => while ecx != 0 { ww(edi as usize, eax as u16); edi = edi.wrapping_add(2); ecx -= 1; },
            "rep stosb" => while ecx != 0 { wb(edi as usize, eax as u8); edi = edi.wrapping_add(1); ecx -= 1; },
            "repe cmpsb" => while ecx != 0 {
                let a = rb(esi as usize) as u32;
                let b = rb(edi as usize) as u32;
                esi = esi.wrapping_add(1);
                edi = edi.wrapping_add(1);
                ecx -= 1;
                let r = a.wrapping_sub(b) & 0xff;
                fl = Some((r == 0, r & 0x80 != 0, a < b, ((a ^ b) & (a ^ r)) & 0x80 != 0, r.count_ones() & 1 == 0));
                if a != b {
                    break;
                }
            },
            "repne scasb" => while ecx != 0 {
                let a = eax & 0xff;
                let b = rb(edi as usize) as u32;
                edi = edi.wrapping_add(1);
                ecx -= 1;
                let r = a.wrapping_sub(b) & 0xff;
                fl = Some((r == 0, r & 0x80 != 0, a < b, ((a ^ b) & (a ^ r)) & 0x80 != 0, r.count_ones() & 1 == 0));
                if a == b {
                    break;
                }
            },
            _ => {}
        }
        (eax, ecx, esi, edi, fl)
    }
}

struct Fun {
    name: &'static str,
    addr: usize,
    body: &'static [u8],
    /// Static call sites in the body (the "expected" count per call when no branch is skipped).
    sites: u32,
    calls: AtomicU32,
    done: AtomicU32,
    first: AtomicBool,
}

macro_rules! fun {
    ($name:expr, $addr:expr, $body:expr, $sites:expr) => {
        Fun {
            name: $name,
            addr: $addr,
            body: &$body,
            sites: $sites,
            calls: AtomicU32::new(0),
            done: AtomicU32::new(0),
            first: AtomicBool::new(false),
        }
    };
}

/// Thunk: captures every register and the stack-argument pointer, runs the Rust body, returns EAX.
macro_rules! thunk {
    ($name:ident, $idx:expr, $ret:literal) => {
        #[unsafe(naked)]
        extern "C" fn $name() {
            std::arch::naked_asm!(
                "push ebp", "push ebx", "push edi", "push esi", "push edx", "push ecx", "push eax",
                "lea eax, [esp + 32]",
                "push eax",
                "push {i}",
                "call {f}",
                "add esp, 36",
                $ret,
                i = const $idx,
                f = sym run,
            )
        }
    };
}

extern "C" fn run(idx: u32, args: *const u32, eax: u32, ecx: u32, edx: u32, esi: u32, edi: u32, ebx: u32, ebp: u32) -> u32 {
    let (ret, n) = unsafe { dispatch(idx, args, eax, ecx, edx, esi, edi, ebx, ebp) };
    let f = &FUNS[idx as usize];
    f.calls.fetch_add(1, Ordering::Relaxed);
    f.done.fetch_add(n, Ordering::Relaxed);
    if !f.first.swap(true, Ordering::Relaxed) {
        log(&format!(
            "port_tables: {} first call: {} call sites executed (expected {} in the body), eax={:#x}",
            f.name, n, f.sites, ret
        ));
    }
    ret
}

/// Install this module's replacements (called from hooks::install_all).
pub fn install() {
    let mut ok = 0;
    let mut entries = 0;
    for (i, f) in FUNS.iter().enumerate() {
        if f.addr == 0x50d000 {
            continue; // xtbl_load_effects failed the native differential test
        }
        entries += f.sites;
        if replace_pinned(f.name, f.addr, f.body, THUNKS[i] as usize) {
            ok += 1;
        }
    }
    log(&format!("port_tables: replaced {ok}/{} with Rust ({entries} entries)", FUNS.len()));
}

/// Per-function call counts for the periodic log.
pub fn summary() -> String {
    let parts: Vec<String> = FUNS
        .iter()
        .filter_map(|f| {
            let c = f.calls.load(Ordering::Relaxed);
            (c > 0).then(|| format!("{} {c} ({} / {})", f.name, f.done.load(Ordering::Relaxed), c as usize * f.sites as usize))
        })
        .collect();
    if parts.is_empty() { String::new() } else { format!("port_tables: {}", parts.join(", ")) }
}


